application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root { --ink:#20252b; --muted:#707983; --line:#e5e8e8; --cream:#f6f7f3; --teal:#176d68; --teal-dark:#105550; --coral:#e9866d; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; background:var(--cream); color:var(--ink); font-family:'DM Sans',sans-serif; }
.app-shell { width:min(1080px, calc(100% - 40px)); margin:0 auto; padding:64px 0 36px; }
.hero { display:flex; align-items:center; gap:20px; margin-bottom:44px; }
.brand-mark { width:52px; height:52px; display:grid; place-items:center; border-radius:16px; color:white; background:var(--teal); font-size:26px; box-shadow:0 8px 18px #176d6830; }
.eyebrow { margin:0 0 8px; color:var(--teal); font-size:11px; font-weight:700; letter-spacing:1.7px; }
h1,h2,h3,p { margin-top:0; } h1,h2 { font-family:'Playfair Display',serif; letter-spacing:-.5px; }
h1 { margin-bottom:8px; font-size:clamp(34px,5vw,50px); line-height:1.05; } .intro { margin:0; color:var(--muted); }
.content-grid { display:grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); gap:24px; align-items:start; }
.card { background:#fff; border:1px solid #e9ecea; border-radius:20px; padding:30px; box-shadow:0 12px 35px #26332b0a; }
.section-heading { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:28px; } h2 { margin:0; font-size:26px; } .step-badge,.count { display:grid; place-items:center; border-radius:50%; font-size:12px; font-weight:700; }
.step-badge { width:34px; height:34px; background:#edf5f2; color:var(--teal); } .count { min-width:32px; height:32px; padding:0 9px; background:#f2eee8; color:#906b3d; }
.field { margin-bottom:18px; } .field-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
label { display:block; margin-bottom:8px; font-size:13px; font-weight:600; } input,select { width:100%; border:1px solid var(--line); border-radius:10px; padding:13px 14px; color:var(--ink); background:#fcfdfc; font:inherit; font-size:14px; outline:none; transition:.2s; }
input:focus,select:focus { border-color:var(--teal); box-shadow:0 0 0 3px #176d6815; } input:invalid:not(:placeholder-shown) { border-color:#d98572; }
.primary-button { width:100%; margin-top:6px; border:0; border-radius:10px; padding:14px 18px; color:#fff; background:var(--teal); font:600 14px 'DM Sans',sans-serif; cursor:pointer; transition:.2s; } .primary-button:hover { background:var(--teal-dark); transform:translateY(-1px); } .primary-button span { margin-left:8px; font-size:18px; }
.form-error { min-height:18px; margin:0 0 3px; color:#bd5f4d; font-size:12px; }
.booking-list { display:flex; flex-direction:column; gap:12px; } .empty-state { text-align:center; padding:42px 20px; border:1px dashed #dce2df; border-radius:14px; color:var(--muted); } .empty-icon { margin:auto auto 13px; width:42px; height:42px; display:grid; place-items:center; border-radius:50%; background:#f5eee6; color:#b77b47; font-size:23px; } .empty-state h3 { margin-bottom:7px; color:var(--ink); font-size:15px; } .empty-state p { margin:0; font-size:13px; line-height:1.5; }
.confirmation { margin:-8px 0 18px; padding:11px 13px; border-radius:9px; color:#23634f; background:#eaf6ef; font-size:13px; font-weight:600; }
.booking-item { position:relative; padding:18px; border:1px solid var(--line); border-radius:13px; background:#fff; } .booking-item.cancelled { opacity:.65; background:#f7f8f7; } .booking-top { display:flex; justify-content:space-between; gap:12px; } .booking-name { margin:0 0 4px; font-weight:700; } .booking-type { margin:0; color:var(--teal); font-size:12px; font-weight:600; } .booking-meta { display:flex; flex-wrap:wrap; gap:8px 16px; margin-top:14px; color:var(--muted); font-size:12px; } .booking-meta span { display:flex; gap:5px; align-items:center; } .cancel-button { border:0; padding:5px 0; background:none; color:#a86455; font:600 12px 'DM Sans',sans-serif; cursor:pointer; } .cancel-button:hover { text-decoration:underline; } .cancelled-label { color:#8b9290; font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:1px; }
.privacy-note { margin:24px 0 0; text-align:center; color:#89918d; font-size:12px; } .privacy-note span { margin-right:5px; color:var(--teal); }
@media (max-width:760px) { .app-shell { padding-top:35px; } .content-grid { grid-template-columns:1fr; } .card { padding:23px; } }
@media (max-width:430px) { .field-row { grid-template-columns:1fr; gap:0; } }

application.javascript:
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('booking-form');
  const dateInput = document.querySelector('[data-testid="booking-date"]');
  const list = document.querySelector('[data-testid="booking-list"]');
  const empty = document.getElementById('empty-state');
  const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
  const error = document.getElementById('form-error');
  const count = document.getElementById('booking-count');
  const bookings = [];

  const today = new Date();
  const localToday = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().split('T')[0];
  dateInput.min = localToday;

  function formatDate(value) {
    return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric', year:'numeric' });
  }
  function render() {
    list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
    empty.hidden = bookings.length > 0;
    count.textContent = bookings.filter(item => !item.cancelled).length;
    bookings.forEach(item => {
      const article = document.createElement('article');
      article.className = 'booking-item' + (item.cancelled ? ' cancelled' : '');
      article.dataset.testid = 'booking';
      article.dataset.status = item.cancelled ? 'cancelled' : 'active';
      const top = document.createElement('div'); top.className = 'booking-top';
      const details = document.createElement('div');
      const name = document.createElement('p'); name.className = 'booking-name'; name.dataset.testid = 'booking-name-display'; name.textContent = item.name;
      const type = document.createElement('p'); type.className = 'booking-type'; type.textContent = item.type;
      details.append(name, type); top.appendChild(details);
      if (item.cancelled) { const label = document.createElement('span'); label.className = 'cancelled-label'; label.textContent = 'Cancelled'; top.appendChild(label); }
      else { const button = document.createElement('button'); button.className = 'cancel-button'; button.dataset.testid = 'booking-cancel'; button.type = 'button'; button.textContent = 'Cancel'; button.addEventListener('click', () => { item.cancelled = true; render(); }); top.appendChild(button); }
      const meta = document.createElement('div'); meta.className = 'booking-meta';
      const date = document.createElement('span'); date.textContent = '◷ ' + formatDate(item.date);
      const time = document.createElement('span'); time.textContent = '◴ ' + item.time;
      meta.append(date, time); article.append(top, meta); list.appendChild(article);
    });
  }
  form.addEventListener('submit', event => {
    event.preventDefault(); error.textContent = '';
    if (!form.checkValidity()) { form.reportValidity(); return; }
    if (dateInput.value < localToday) { error.textContent = 'Please choose today or a future date.'; dateInput.focus(); return; }
    const data = new FormData(form);
    bookings.push({ name:data.get('name').trim(), email:data.get('email'), date:data.get('date'), time:data.get('time'), type:data.get('type'), cancelled:false });
    render(); form.reset(); dateInput.min = localToday;
    confirmation.textContent = 'Booking created successfully — it has been added to your schedule.'; confirmation.hidden = false;
    setTimeout(() => { confirmation.hidden = true; }, 5000);
  });
});
